import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', description: '', telephone: '',
    tarifs_matieres: [], certificats: []
  });
  const [availableMatieres, setAvailableMatieres] = useState([]);
  const [saved, setSaved] = useState(false);

  // États pour l'upload de certificat (Image 2)
  const [showUpload, setShowUpload] = useState(false);
  const [newCert, setNewCert] = useState({ titre: '', description: '' });
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
        const res = await api.get(route);
        setForm(res.data);

        if (user?.role === 'professeur') {
          const resMat = await api.get('/api/admin/referentiel/matieres');
          setAvailableMatieres(resMat.data);
        }
      } catch (e) { console.error("Erreur chargement profil"); }
    };
    fetchData();
  }, [user]);

  // --- LOGIQUE MATIÈRES ET TARIFS (Image 3 & 4) ---
  const handleToggleMatiere = (matiere_id) => {
    let updated = [...(form.tarifs_matieres || [])];
    const index = updated.findIndex(t => t.matiere_id === matiere_id);

    if (index > -1) {
      updated = updated.filter(t => t.matiere_id !== matiere_id); // Décocher
    } else {
      updated.push({ matiere_id, nom_matiere: '', tarif: 20 }); // Cocher (prix par défaut 20)
    }
    setForm({ ...form, matieres_avec_tarifs: updated, tarifs_matieres: updated });
  };

  const handleTarifChange = (matiere_id, val) => {
    const updated = form.tarifs_matieres.map(t => 
      t.matiere_id === matiere_id ? { ...t, tarif: parseFloat(val) } : t
    );
    setForm({ ...form, matieres_avec_tarifs: updated, tarifs_matieres: updated });
  };

  // --- LOGIQUE ENREGISTREMENT PROFIL ---
  async function handleSave() {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      // On s'assure d'envoyer les bons noms de champs au backend
      const payload = { ...form, matieres_avec_tarifs: form.tarifs_matieres };
      await api.put(route, payload);
      setSaved(true); setTimeout(() => setSaved(false), 2000);
    } catch (e) { alert('Erreur lors de la sauvegarde'); }
  }

  // --- LOGIQUE UPLOAD CERTIFICAT (Image 2) ---
  const handleFileUpload = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('titre', newCert.titre);
    formData.append('description', newCert.description);
    formData.append('file', selectedFile);

    try {
      await api.post('/api/professeurs/me/certificats', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setShowUpload(false);
      window.location.reload(); // Rafraîchir pour voir le nouveau diplôme
    } catch (err) { alert("Erreur upload"); }
  };

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', outline: 'none', width: '100%' };

  return (
    <div style={{ padding: 32, maxWidth: 1100, margin: '0 auto' }}>
      <div style={{ fontFamily: 'Syne', fontSize: '1.5rem', fontWeight: 700, marginBottom: 24 }}>⚙️ Paramètres du compte</div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 30 }}>

        {/* COLONNE GAUCHE */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>

          {/* IDENTITÉ (Image 1) */}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
            <div style={{ fontWeight: 600, marginBottom: 20 }}>👤 Informations personnelles</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
               <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                  <div><label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Prénom</label><input style={inp} value={form.user_prenom || ''} readOnly /></div>
                  <div><label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Nom</label><input style={inp} value={form.user_nom || ''} readOnly /></div>
               </div>
               <div><label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Email</label><input style={inp} value={form.email || ''} readOnly /></div>
               <div>
                 <label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Ville de résidence</label>
                 <input style={inp} value={form.ville || ''} onChange={e => setForm({...form, ville: e.target.value})} />
               </div>
               <button onClick={handleSave} style={{ background: 'var(--accent)', color: '#fff', border: 'none', padding: 12, borderRadius: 10, fontWeight: 600, cursor: 'pointer' }}>
                 {saved ? '✅ Enregistré' : 'Sauvegarder les modifications'}
               </button>
            </div>
          </div>

          {/* SECTION CERTIFICATS (Image 2) */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
                <div style={{ fontWeight: 600, marginBottom: 16 }}>📜 Certificats et Diplômes</div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                    {form.certificats?.map(c => (
                        <div key={c.id} style={{ background: 'var(--surface2)', padding: 12, borderRadius: 12, border: '1px solid var(--border)' }}>
                            <div style={{ fontWeight: 600, fontSize: '.85rem' }}>{c.titre}</div>
                            <a href={`http://localhost:8001${c.fichier_url}`} target="_blank" rel="noreferrer" style={{ color: 'var(--accent)', fontSize: '.75rem', textDecoration: 'underline' }}>Voir le document</a>
                        </div>
                    ))}
                    <div 
                        onClick={() => setShowUpload(true)}
                        style={{ border: '2px dashed var(--border)', borderRadius: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20, cursor: 'pointer', textAlign: 'center' }}
                    >
                       <span style={{ fontSize: '.8rem', color: 'var(--accent)' }}>+ Ajouter un diplôme</span>
                    </div>
                </div>
            </div>
          )}
        </div>

        {/* COLONNE DROITE : MATIÈRES ET TARIFS (Image 3 & 4) */}
        {user?.role === 'professeur' && (
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
            <div style={{ fontWeight: 600, marginBottom: 16 }}>📚 Matières enseignées & Tarifs</div>
            <p style={{ fontSize: '.85rem', color: 'var(--text2)', marginBottom: 20 }}>Cochez vos domaines d'expertise et fixez vos tarifs horaires.</p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {availableMatieres.map(m => {
                    const activeTarif = form.tarifs_matieres?.find(t => t.matiere_id === m.id);
                    return (
                        <div key={m.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 15px', background: activeTarif ? 'rgba(108,99,255,.05)' : 'transparent', borderRadius: 12, border: activeTarif ? '1px solid var(--accent)' : '1px solid var(--border)' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                                <input 
                                  type="checkbox" 
                                  style={{ width: 18, height: 18, cursor: 'pointer' }}
                                  checked={!!activeTarif} 
                                  onChange={() => handleToggleMatiere(m.id)} 
                                />
                                <span style={{ fontSize: '.95rem', fontWeight: activeTarif ? 600 : 400 }}>{m.nom}</span>
                            </div>
                            {activeTarif && (
                                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                    <input 
                                        type="number" 
                                        value={activeTarif.tarif} 
                                        onChange={(e) => handleTarifChange(m.id, e.target.value)} 
                                        style={{ ...inp, width: 70, padding: '6px', textAlign: 'center', background: 'var(--bg)' }} 
                                    />
                                    <span style={{ fontSize: '.8rem', fontWeight: 600 }}>DT/H</span>
                                </div>
                            )}
                        </div>
                    )
                })}
            </div>
            <button onClick={handleSave} style={{ width: '100%', background: 'none', border: '1px solid var(--accent)', color: 'var(--accent)', padding: 12, borderRadius: 10, marginTop: 20, fontWeight: 600, cursor: 'pointer' }}>
                Enregistrer les tarifs
            </button>
          </div>
        )}
      </div>

      {/* MODALE D'UPLOAD (Image 2) */}
      {showUpload && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.85)', zIndex: 2000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
            <div style={{ background: 'var(--surface)', padding: 30, borderRadius: 24, width: '100%', maxWidth: 450, border: '1px solid var(--border)' }}>
                <h3 style={{ fontFamily: 'Syne', marginBottom: 20 }}>📁 Ajouter un certificat</h3>
                <form onSubmit={handleFileUpload}>
                    <div style={{ marginBottom: 15 }}>
                        <label style={{ fontSize: '.8rem', color: 'var(--text2)' }}>Titre du diplôme</label>
                        <input style={inp} placeholder="Ex: Master en Intelligence Artificielle" onChange={e => setNewCert({...newCert, titre: e.target.value})} required />
                    </div>
                    <div style={{ marginBottom: 15 }}>
                        <label style={{ fontSize: '.8rem', color: 'var(--text2)' }}>Description (optionnel)</label>
                        <textarea style={{ ...inp, height: 80, resize: 'none' }} placeholder="Détails sur l'obtention..." onChange={e => setNewCert({...newCert, description: e.target.value})} />
                    </div>
                    <div style={{ marginBottom: 25 }}>
                        <label style={{ fontSize: '.8rem', color: 'var(--text2)' }}>Fichier (PDF ou Image)</label>
                        <input type="file" onChange={e => setSelectedFile(e.target.files[0])} required style={{ display: 'block', marginTop: 10, color: 'var(--text2)' }} />
                    </div>
                    <div style={{ display: 'flex', gap: 12 }}>
                        <button type="submit" style={{ flex: 2, background: 'var(--accent)', color: '#fff', border: 'none', padding: 12, borderRadius: 12, fontWeight: 600, cursor: 'pointer' }}>Enregistrer</button>
                        <button type="button" onClick={() => setShowUpload(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', border: 'none', padding: 12, borderRadius: 12, cursor: 'pointer' }}>Annuler</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
}
